// Merges the texts of the giant built-in templates (generated by the backend into ../backend/internal/projects/giant_i18n.json
// as {"es": {key: text}, "en": {...}}) into src/lib/i18n/es.json and en.json. Idempotent: existing keys keep their position
// (their text is updated if it differs); new keys are added after the last "proj.*" key.
import fs from "node:fs";
import path from "node:path";

const source = path.resolve("../backend/internal/projects/giant_i18n.json");
if (!fs.existsSync(source)) {
  console.error(`not found: ${source}`);
  process.exit(1);
}
const giant = JSON.parse(fs.readFileSync(source, "utf8"));
let changed = 0;
for (const loc of ["es", "en"]) {
  const file = path.resolve(`src/lib/i18n/${loc}.json`);
  const cat = JSON.parse(fs.readFileSync(file, "utf8"));
  const incoming = giant[loc] || {};
  const fresh = [];
  let updated = 0;
  for (const [k, v] of Object.entries(incoming)) {
    if (!(k in cat)) fresh.push([k, v]);
    else if (cat[k] !== v) { cat[k] = v; updated++; }
  }
  let out = cat;
  if (fresh.length) {
    const keys = Object.keys(cat);
    let at = keys.length - 1;
    for (let i = keys.length - 1; i >= 0; i--) if (keys[i].startsWith("proj.")) { at = i; break; }
    out = {};
    keys.forEach((k, i) => {
      out[k] = cat[k];
      if (i === at) for (const [nk, nv] of fresh) out[nk] = nv;
    });
  }
  if (fresh.length || updated) {
    fs.writeFileSync(file, JSON.stringify(out, null, 2) + "\n");
    changed++;
  }
  console.log(`${loc}: +${fresh.length} new, ${updated} updated`);
}
console.log(changed ? "merged" : "already up to date");
